 "content": "from collections import Counter


def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if not rows or not cols:
        return [row[:] for row in grid]

    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = max((color for color in counts if color != background), key=lambda color: counts[color])
    out = [row[:] for row in grid]

    for r in range(rows):
        points = [c for c in range(cols) if grid[r][c] == marker]
        if len(points) >= 2:
            for c in range(min(points), max(points) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(cols):
        points = [r for r in range(rows) if grid[r][c] == marker]
        if len(points) >= 2:
            for r in range(min(points), max(points) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
